const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const pittsburgh = ee.Geometry.Point([-79.9959, 40.4406]);
    const dataset = 'ECMWF/ERA5/MONTHLY';
    const band = 'mean_2m_air_temperature';
    const scale = 1000; // Scale for reduceRegion, ERA5 native res is ~27.8km

    // 2. Data Acquisition & Check for 2018
    const collection2018 = ee.ImageCollection(dataset)
        .filterBounds(pittsburgh)
        .filterDate('2018-02-01', '2018-02-28')
        .select(band);

    const size2018 = collection2018.size().getInfo();
    if (size2018 === 0) {
        console.log("No image found for February 2018.");
        console.log("A"); // The tag should be printed on the last line
        return;
    }
    const image2018 = collection2018.first();

    // 3. Data Acquisition & Check for 2010-2017
    const collectionBaseline = ee.ImageCollection(dataset)
        .filterBounds(pittsburgh)
        .filterDate('2010-01-01', '2017-12-31')
        .filter(ee.Filter.calendarRange(2, 2, 'month'))
        .select(band);

    const sizeBaseline = collectionBaseline.size().getInfo();
    if (sizeBaseline === 0) {
        console.log("No images found for the baseline period (2010-2017).");
        console.log("C1");
        return;
    }
    const meanBaseline = collectionBaseline.mean();

    // 4. Calculation
    const temp2018Result = image2018.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: pittsburgh,
        scale: scale,
        maxPixels: 1e9
    }).get(band);

    const tempBaselineResult = meanBaseline.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: pittsburgh,
        scale: scale,
        maxPixels: 1e9
    }).get(band);

    const temp2018K = temp2018Result.getInfo();
    const tempBaselineK = tempBaselineResult.getInfo();

    // 5. Validation & Final Answer
    if (temp2018K === null || tempBaselineK === null) {
        console.log("Calculation failed: could not extract temperature value.");
        console.log("C3");
        return;
    }

    // Convert from Kelvin to Celsius for better readability
    const temp2018C = temp2018K - 273.15;
    const tempBaselineC = tempBaselineK - 273.15;

    console.log(`Pittsburgh Feb 2018 Mean Temp: ${temp2018C.toFixed(2)} C`);
    console.log(`Pittsburgh 2010-2017 Feb Avg Temp: ${tempBaselineC.toFixed(2)} C`);
    console.log(`Baseline Image Count: ${sizeBaseline}`);

    if (temp2018C > tempBaselineC) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
